{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Keep the 20% cap and 18-month period off the table unless Amelia gives the required draft-specific written authority."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Require AUD 5,000 de minimis and AUD 50,000 tipping basket, with recovery from the first dollar once exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Reject 18 months absent Amelia’s written approval. Require 24 months after Completion."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Require a separate 100%-of-price cap and at least six years, outside the general basket, de minimis and knowledge bar."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "preserve claims for fraud, wilful concealment and deliberate misconduct from all caps, baskets, time limits, exclusive remedies and non-reliance"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject deemed disclosure of the whole data room, Accounts, registers and public records"
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the blanket Buyer-knowledge bar."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "require an effective consent and evidence that all conditions are satisfied before Completion. Delivery alone and reasonable endeavours are insufficient."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require a current payout statement, direct repayment from Completion funds and effective security releases at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require an express funds-flow line item or Seller funding, including any triggered on-costs once established."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Seek a broader, separate IP indemnity and title cure"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Reject the unsupported assurance that DD-006 is immaterial. Require preservation of logs and evidence, investigation, Buyer updates and appropriate pre-Completion cooperation/remediation."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Do not automatically classify it as Debt or deduct it from price; equally, do not accept the Seller’s ordinary-course label without evidence."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "return a mark-up preserving separate regimes for general warranties, Fundamental/Title, Tax, IP, payment and covenants"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require independent checks and deliverables covering ownership, all issued shares, encumbrances and Seller authority."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Negotiate their warranties, indemnities and limitations separately; do not assume either unlimited liability or that the general regime resolves them."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

